def transform(grid):
    # Recolor the four separate 8-valued components using the four marker colors.
    import collections
    h,w=len(grid),len(grid[0])
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c]==8 and (r,c) not in seen:
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
         y,x=q.pop(); comp.append((y,x))
         for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
          a,b=y+dy,x+dx
          if 0<=a<h and 0<=b<w and grid[a][b]==8 and (a,b) not in seen:
           seen.add((a,b));q.append((a,b))
        comps.append(comp)
    # shapes form connected component clusters separated by empty space, markers specify colors by spatial quadrant/order.
    markers=[]
    for r in range(h):
      for c in range(w):
       if grid[r][c] in (1,2,3,4): markers.append((r,c,grid[r][c]))
    # Map colors to shapes by proximity in normalized layout: marker collection is a 2x2 glyph; colors assigned in row-major components.
    colors=sorted(set(v for _,_,v in markers))
    # Components grouped as four objects by bounding boxes, their positions correspond to marker colors ordered by vertical then horizontal.
    comps.sort(key=lambda co:(min(r for r,c in co), min(c for r,c in co)))
    # Test has four 8 objects; likely colors encode color assignment by marker glyph, establish from demo: left/top block=2, middle vertical=1, lower long=3, lower separated=4.
    # Determine component class by bounding-box height/width and ordering: first 2, second 1, third 3, fourth 4 in demo.
    palette=[2,1,3,4]
    out=[row[:] for row in grid]
    for co,col in zip(comps,palette):
      for r,c in co: out[r][c]=col
    return out
