def transform(grid):
    out=[row[:] for row in grid]
    # Four-by-four tiles of the 8 silhouette are colored in reading order by the marker colors.
    labels=[]
    for row in grid:
        for v in row:
            if v in (1,2,3,4): labels.append(v)
    tiles=[]
    h,w=len(grid),len(grid[0])
    for r in range(0,h,4):
      for c in range(0,w,4):
        cells=[(y,x) for y in range(r,min(r+4,h)) for x in range(c,min(c+4,w)) if grid[y][x]==8]
        if cells: tiles.append(cells)
    # group the cells into the 4x4 blocks and map by marker color multiplicities, row-major.
    for cells,color in zip(tiles,labels):
      for y,x in cells: out[y][x]=color
    return out
